"""Routes for Candidates, generated by Dryv; the engine implements StagingCandidatesService."""

from __future__ import annotations

from abc import ABC, abstractmethod
from collections.abc import Awaitable, Callable
from typing import Annotated
from uuid import UUID

from fastapi import APIRouter, Body, Depends, Path, Query, Request

from mzizi_engine.api.schemas.api.staging.models.candidate_list import CandidateList
from mzizi_engine.api.schemas.api.staging.models.decision_body import DecisionBody
from mzizi_engine.api.schemas.mongo.staging.enums.candidate_kind import CandidateKind
from mzizi_engine.api.schemas.mongo.staging.enums.candidate_status import CandidateStatus
from mzizi_engine.api.schemas.mongo.staging.models.candidate import Candidate

__all__ = ["StagingCandidatesService", "build_staging_candidates_router"]

type Guard = Callable[[Request], Awaitable[None]]
"""An async FastAPI dependency that raises 401 or 403 before the route runs."""


class StagingCandidatesService(ABC):
    """What Candidates needs from handwritten code. Raise ``fastapi.HTTPException`` for failures."""

    @abstractmethod
    async def decide_candidate(self, *, candidate_id: UUID, decision: DecisionBody) -> Candidate:
        """Record a review decision. Approval queues promotion through the change ledger; nothing is written to domain tables here."""

    @abstractmethod
    async def get_candidate(self, *, candidate_id: UUID) -> Candidate:
        """One candidate with its payload, confidence and the captures it came from."""

    @abstractmethod
    async def list_candidates(
        self, *, kind: CandidateKind | None, status: CandidateStatus | None, limit: int | None
    ) -> CandidateList:
        """Candidates awaiting or past review, optionally by kind or status."""


def build_staging_candidates_router(service: StagingCandidatesService, guard: Guard | None = None) -> APIRouter:
    """Routes for Candidates, delegating to ``service``; ``guard`` protects every route."""

    router = APIRouter(tags=["Candidates"], dependencies=[Depends(guard)] if guard else [])

    @router.post(
        "/v1/candidates/{candidateId}/decision",
        response_model=Candidate,
        status_code=200,
        summary="Record a review decision. Approval queues promotion through the change ledger; nothing is written to domain tables here.",
    )
    async def decide_candidate(
        candidate_id: Annotated[UUID, Path(alias="candidateId")],
        decision: Annotated[DecisionBody, Body()],
    ) -> Candidate:
        return await service.decide_candidate(candidate_id=candidate_id, decision=decision)

    @router.get(
        "/v1/candidates/{candidateId}",
        response_model=Candidate,
        status_code=200,
        summary="One candidate with its payload, confidence and the captures it came from.",
    )
    async def get_candidate(
        candidate_id: Annotated[UUID, Path(alias="candidateId")],
    ) -> Candidate:
        return await service.get_candidate(candidate_id=candidate_id)

    @router.get(
        "/v1/candidates",
        response_model=CandidateList,
        status_code=200,
        summary="Candidates awaiting or past review, optionally by kind or status.",
    )
    async def list_candidates(
        kind: Annotated[CandidateKind | None, Query(alias="kind")] = None,
        status: Annotated[CandidateStatus | None, Query(alias="status")] = None,
        limit: Annotated[int | None, Query(alias="limit")] = None,
    ) -> CandidateList:
        return await service.list_candidates(kind=kind, status=status, limit=limit)

    return router
